// DeleteHelmWorkloadInstanceCmd represents the command 'tptctl delete helm-workload-instance'
var DeleteHelmWorkloadInstanceCmd = &cobra.Command{
	Example: "  # delete using a config file\n  tptctl delete helm-workload-instance --config path/to/config.yaml\n\n  # delete using name\n  tptctl delete helm-workload-instance --name some-helm-workload-instance",
	Long:    "Delete an existing helm workload instance.",
	PreRun:  CommandPreRunFunc,
	Run: func(cmd *cobra.Command, args []string) {
		apiClient, _, apiEndpoint, _ := GetClientContext(cmd)

		// flag validation
		if err := cli.ValidateConfigNameFlags(
			helmWorkloadConfigPath,
			helmWorkloadName,
			"helm workload instance",
		); err != nil {
			cli.Error("flag validation failed", err)
			os.Exit(1)
		}

		// delete helm workload instance based on version
		switch helmWorkloadVersion {
		case "v0":
			var helmWorkloadInstanceConfig config_v0.HelmWorkloadInstanceConfig
			if helmWorkloadConfigPath != "" {
				// load helm workload instance config
				configContent, err := os.ReadFile(helmWorkloadConfigPath)
				if err != nil {
					cli.Error("failed to read config file", err)
					os.Exit(1)
				}
				if err := yaml.UnmarshalStrict(configContent, &helmWorkloadInstanceConfig); err != nil {
					cli.Error("failed to unmarshal config file yaml content", err)
					os.Exit(1)
				}
			} else {
				helmWorkloadInstanceConfig = config_v0.HelmWorkloadInstanceConfig{
					HelmWorkloadInstance: config_v0.HelmWorkloadInstanceValues{
						Name: &helmWorkloadName,
					},
				}
			}

			// delete helm workload instance
			helmWorkloadInstanceConfig.HelmWorkloadInstance.HelmWorkloadConfigPath = &helmWorkloadConfigPath
			deletedHelmWorkloadInstance, err := helmWorkloadInstanceConfig.Delete(apiClient, apiEndpoint)
			if err != nil {
				cli.Error("failed to delete helm workload instance", err)
				os.Exit(1)
			}

			cli.Complete(fmt.Sprintf("helm workload instance %s deleted", *deletedHelmWorkloadInstance.HelmWorkloadInstance.Name))
		default:
			cli.Error("", errors.New("unrecognized object version"))
			os.Exit(1)
		}
	},
	Short:        "Delete an existing helm workload instance",
	SilenceUsage: true,
	Use:          "helm-workload-instance",
}

